INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1943349, 267632, 39144, '<td valign="top">I don''t know how you could have kept this within the editing rules, but kudos to you if you did. Excellent photo! 10 if it''s still in at the end!</td>', 'I don''t know how you could have kept this within the editing rules, but kudos to you if you did. Excellent photo! 10 if it''s still in at the end!', '2005-12-12 00:19:28.000000', NULL, 1),
(1943351, 267370, 42826, '<td valign="top">This is a sweet shot...very creative!</td>', 'This is a sweet shot...very creative!', '2005-12-12 00:20:07.000000', NULL, 1),
(1943354, 267632, 24976, '<td valign="top">the photo is very good, but imo the border and the text are just silly and take away from the finished piece.</td>', 'the photo is very good, but imo the border and the text are just silly and take away from the finished piece.', '2005-12-12 00:20:53.000000', NULL, 1),
(1943356, 267522, 42826, '<td valign="top">Wow, that''s amazing...better than mine i would say!</td>', 'Wow, that''s amazing...better than mine i would say!', '2005-12-12 00:21:33.000000', NULL, 1),
(1943361, 267534, 42826, '<td valign="top">i want one...nice DoF</td>', 'i want one...nice DoF', '2005-12-12 00:22:41.000000', NULL, 1),
(1943365, 267935, 24976, '<td valign="top">the reflection of the room in the ball really kills the shot, everything else is so well done and with so much attention to details, this being an advanced challenge i would have suggested selecing that area with a feathered selection and applying a guassian blur to remove that reflection, or manually with the blur tool... or with the clone tool...</td>', 'the reflection of the room in the ball really kills the shot, everything else is so well done and with so much attention to details, this being an advanced challenge i would have suggested selecing that area with a feathered selection and applying a guassian blur to remove that reflection, or manually with the blur tool... or with the clone tool...', '2005-12-12 00:23:22.000000', NULL, 1),
(1943367, 267257, 15711, '<td valign="top">I like the tight macro shot.  Beautiful colors and undulating texture!!</td>', 'I like the tight macro shot.  Beautiful colors and undulating texture!!', '2005-12-12 00:23:40.000000', NULL, 1),
(1943369, 267417, 39144, '<td valign="top">I''ve tried a shot like this before, and with the same results in the reflection with the ghosting. One comment was made to me about the lighting, and if there was more than one light. I guess multiple lights will do that to the reflection. Just food for thought!</td>', 'I''ve tried a shot like this before, and with the same results in the reflection with the ghosting. One comment was made to me about the lighting, and if there was more than one light. I guess multiple lights will do that to the reflection. Just food for thought!', '2005-12-12 00:24:03.000000', NULL, 1),
(1943375, 268268, 35786, '<td valign="top">nice colors &amp; texture, I just don''t think the tilt is working here. not enough to be a good angle and too much to be not on purpose. very cool other than that :0) 6 for now...</td>', 'nice colors & texture, I just don''t think the tilt is working here. not enough to be a good angle and too much to be not on purpose. very cool other than that :0) 6 for now...', '2005-12-12 00:25:49.000000', NULL, 1),
(1943376, 268033, 15711, '<td valign="top">This has good lighting and great DOF but in a catalog, I never see wine in the goblets. Usually they are trying to sell the glasses and showcase them. I feel as if they are a tad too centered. Maybe shooting from a slightly different angle would look more like a true advertising type shot to me.</td>', 'This has good lighting and great DOF but in a catalog, I never see wine in the goblets. Usually they are trying to sell the glasses and showcase them. I feel as if they are a tad too centered. Maybe shooting from a slightly different angle would look more like a true advertising type shot to me.', '2005-12-12 00:26:15.000000', NULL, 1),
(1943386, 268200, 22379, '<td valign="top">eeee! Stripey socks! Love it! (sorry if anyone comments thinking this is me, i am on a stripey sock crucade!!)</td>', 'eeee! Stripey socks! Love it! (sorry if anyone comments thinking this is me, i am on a stripey sock crucade!!)', '2005-12-12 00:29:04.000000', NULL, 1),
(1943387, 267515, 15711, '<td valign="top">This is nicely presented.  Not crazy about the pine cone in the lower right, but that''s being nit picky. The detail is good which can be hard with white bisque porcelain. I like the blurred lights in the background too. IT doesn''t have a true catalog feel to me, but more like a nice display in a little specialty shop.</td>', 'This is nicely presented.  Not crazy about the pine cone in the lower right, but that''s being nit picky. The detail is good which can be hard with white bisque porcelain. I like the blurred lights in the background too. IT doesn''t have a true catalog feel to me, but more like a nice display in a little specialty shop.', '2005-12-12 00:29:04.000000', NULL, 1),
(1943389, 268227, 42826, '<td valign="top">i love what you have done with this shot.  very warming...soothing....</td>', 'i love what you have done with this shot.  very warming...soothing....', '2005-12-12 00:30:04.000000', NULL, 1),
(1943391, 267903, 15711, '<td valign="top">I can see this on the cover with Holiday 2005 in the negative space area at the top and bottom. I love the gold and red against the white.  Beautiful detail.  Nicely done.</td>', 'I can see this on the cover with Holiday 2005 in the negative space area at the top and bottom. I love the gold and red against the white.  Beautiful detail.  Nicely done.', '2005-12-12 00:30:08.000000', NULL, 1),
(1943394, 268294, 42826, '<td valign="top">the pieces in her face are kinda distracting...but cute shot...</td>', 'the pieces in her face are kinda distracting...but cute shot...', '2005-12-12 00:30:42.000000', NULL, 1),
(1943397, 267351, 42826, '<td valign="top">yikes...santa please don''t bring me that!  Oh wait i am not a man, whew</td>', 'yikes...santa please don''t bring me that!  Oh wait i am not a man, whew', '2005-12-12 00:31:18.000000', NULL, 1),
(1943398, 268284, 15711, '<td valign="top">Very pretty. I can see this on the cover of a specialty catalog. I like that the ornaments are satin and not real shiny.  The lighting is good and the DOF is nicely done.</td>', 'Very pretty. I can see this on the cover of a specialty catalog. I like that the ornaments are satin and not real shiny.  The lighting is good and the DOF is nicely done.', '2005-12-12 00:31:19.000000', NULL, 1),
(1943402, 268179, 42826, '<td valign="top">can i have the lense?????</td>', 'can i have the lense?????', '2005-12-12 00:31:59.000000', NULL, 1),
(1943406, 267333, 35786, '<td valign="top">you could have lost the whole top of this image &amp; cropped it to horizontal. The background is kinda distracting. nice clean image other than that tho...</td>', 'you could have lost the whole top of this image & cropped it to horizontal. The background is kinda distracting. nice clean image other than that tho...', '2005-12-12 00:32:56.000000', NULL, 1),
(1943409, 267632, 28742, '<td valign="top">Uh oh! No text allowed. DQ unless you did it "magically".  I''m giving it a 10 though, in case it''s legit. Good luck.</td>', 'Uh oh! No text allowed. DQ unless you did it "magically".  I''m giving it a 10 though, in case it''s legit. Good luck.', '2005-12-12 00:33:18.000000', NULL, 1),
(1943417, 267819, 15711, '<td valign="top">AWESOME! Looks like a Sharper Image or similar catalog page or cover.  Great detail and I love the perspective up the styrofoam snow. Well done!!!</td>', 'AWESOME! Looks like a Sharper Image or similar catalog page or cover.  Great detail and I love the perspective up the styrofoam snow. Well done!!!', '2005-12-12 00:34:50.000000', NULL, 1),
(1943418, 268026, 28742, '<td valign="top">For a catalog pic, cropping part of the product is not advisable, but a great pic otherwise.</td>', 'For a catalog pic, cropping part of the product is not advisable, but a great pic otherwise.', '2005-12-12 00:34:50.000000', NULL, 1),
(1943421, 267358, 22379, '<td valign="top">Love the rouge! Too cute!</td>', 'Love the rouge! Too cute!', '2005-12-12 00:35:55.000000', NULL, 1),
(1943427, 267895, 15711, '<td valign="top">Very pretty. I love the blurred lights. I can see this on a cover of a catalog for sure.</td>', 'Very pretty. I love the blurred lights. I can see this on a cover of a catalog for sure.', '2005-12-12 00:37:06.000000', NULL, 1),
(1943434, 268051, 24976, '<td valign="top">color might have been better imo. good on the technicals and very ''stock''-ish and sellable. now you just need to make this color...</td>', 'color might have been better imo. good on the technicals and very ''stock''-ish and sellable. now you just need to make this color...', '2005-12-12 00:38:26.000000', NULL, 1),
(1943438, 268208, 15711, '<td valign="top">Beautiful, elegant and stunning.  All it needs is Nieman Marcus 2005 at the top!!  What a gorgeous ornament! I love it''s shadow. Great use of negative space. My single critique would be to possibly not have it centered quite so much.</td>', 'Beautiful, elegant and stunning.  All it needs is Nieman Marcus 2005 at the top!!  What a gorgeous ornament! I love it''s shadow. Great use of negative space. My single critique would be to possibly not have it centered quite so much.', '2005-12-12 00:38:45.000000', NULL, 1),
(1943443, 267873, 15711, '<td valign="top">Cute idea. I like the long shadow.  I think the crop is a tad  too tight above the actual angel and right at the end of the shadow.</td>', 'Cute idea. I like the long shadow.  I think the crop is a tad  too tight above the actual angel and right at the end of the shadow.', '2005-12-12 00:39:41.000000', NULL, 1),
(1943445, 268190, 24976, '<td valign="top">predicting the brown ribbon for this one</td>', 'predicting the brown ribbon for this one', '2005-12-12 00:39:57.000000', NULL, 1),
(1943448, 267333, 42826, '<td valign="top">i think you could have done without whatever was in the background...</td>', 'i think you could have done without whatever was in the background...', '2005-12-12 00:40:23.000000', NULL, 1),
(1943452, 268251, 37779, '<td valign="top">Man, I will give you a score higher just because your title is so funny!</td>', 'Man, I will give you a score higher just because your title is so funny!', '2005-12-12 00:40:47.000000', NULL, 1),
(1943453, 267857, 15711, '<td valign="top">How original! I think I''d eliminate the half nut on the bottom left. Great vivid color and clarity.</td>', 'How original! I think I''d eliminate the half nut on the bottom left. Great vivid color and clarity.', '2005-12-12 00:41:06.000000', NULL, 1),
(1943456, 267722, 48096, '<td valign="top">This photo captures the holiday spirit!!  When the kids wake up early on Christmas day, not only are they excited to see all the new presents they have,.....but they want to know if Santa came by and tasted their cookies!  The look of satisfaction of a kids face, knowing they gave something in return,......is priceless.  :-)<br/>Great Photo!  Deserves Cover Page!</td>', 'This photo captures the holiday spirit!!  When the kids wake up early on Christmas day, not only are they excited to see all the new presents they have,.....but they want to know if Santa came by and tasted their cookies!  The look of satisfaction of a kids face, knowing they gave something in return,......is priceless.  :-)Great Photo!  Deserves Cover Page!', '2005-12-12 00:42:09.000000', NULL, 1),
(1943458, 267828, 15711, '<td valign="top">Nice with the blurred lights in the background.  Simple, vivid and I like the black background. If it were perfect, the flames would be straight up but that''s just nit picking.</td>', 'Nice with the blurred lights in the background.  Simple, vivid and I like the black background. If it were perfect, the flames would be straight up but that''s just nit picking.', '2005-12-12 00:42:25.000000', NULL, 1),
(1943466, 268112, 37779, '<td valign="top">Excellent. I could totally see this in a holiday catalogue. Not a huge fan of the OOF "joy", but the train is great looking. Good work.</td>', 'Excellent. I could totally see this in a holiday catalogue. Not a huge fan of the OOF "joy", but the train is great looking. Good work.', '2005-12-12 00:42:58.000000', NULL, 1),
(1943467, 267151, 24976, '<td valign="top">good photo technically with really nice warm colors, but subject/emotion wise it feels kinda empty to me. the little figurine guy isnt cutting it. 7 for the depth of field, lighting and colors.</td>', 'good photo technically with really nice warm colors, but subject/emotion wise it feels kinda empty to me. the little figurine guy isnt cutting it. 7 for the depth of field, lighting and colors.', '2005-12-12 00:43:42.000000', NULL, 1),
(1943473, 267431, 37779, '<td valign="top">Ah! This makes my eyes go crazy when I look at it...kind of like when you look at a chain linked fence...ANYWHO- this is definatly catalogue material, nice job!</td>', 'Ah! This makes my eyes go crazy when I look at it...kind of like when you look at a chain linked fence...ANYWHO- this is definatly catalogue material, nice job!', '2005-12-12 00:45:49.000000', NULL, 1),
(1943474, 268084, 15711, '<td valign="top">I think the placement of the bow and tinsel is too matchy matchy. I think it''d be more artful if the pendant wasn''t so centered. I''d lay it lazily, and maybe have the earrings together with a tight macro. The bow looks kind of bent and old. I don''t think it even adds to the shot.  I''d remove it, crop it out, so that would help the target center issue of the pendant. The gold of the tinsel mimics the gold chain and the bezel of the earrings. This has definite potential.</td>', 'I think the placement of the bow and tinsel is too matchy matchy. I think it''d be more artful if the pendant wasn''t so centered. I''d lay it lazily, and maybe have the earrings together with a tight macro. The bow looks kind of bent and old. I don''t think it even adds to the shot.  I''d remove it, crop it out, so that would help the target center issue of the pendant. The gold of the tinsel mimics the gold chain and the bezel of the earrings. This has definite potential.', '2005-12-12 00:46:11.000000', NULL, 1),
(1943476, 267819, 28742, '<td valign="top">Absolutely fantastic.</td>', 'Absolutely fantastic.', '2005-12-12 00:47:02.000000', NULL, 1),
(1943480, 268123, 37779, '<td valign="top">Nice "holiday-ish-ey" set up! I wish that fluff ball at the time wasn''t soooo blown out, though. Other than that, pretty good!</td>', 'Nice "holiday-ish-ey" set up! I wish that fluff ball at the time wasn''t soooo blown out, though. Other than that, pretty good!', '2005-12-12 00:47:43.000000', NULL, 1),
(1943483, 267515, 28742, '<td valign="top">Not a fan of the border / vignette, but otherwise great job!</td>', 'Not a fan of the border / vignette, but otherwise great job!', '2005-12-12 00:48:33.000000', NULL, 1),
(1943487, 267345, 28742, '<td valign="top">I use a power saw...</td>', 'I use a power saw...', '2005-12-12 00:49:06.000000', NULL, 1),
(1943489, 267370, 15711, '<td valign="top">Excellent.  I love the simplicity of this.  Great detail and lighting. The string of twinkly lights is wonderful with the colors and the way you captured them.  I wonder if the background were solid black if it wouldn''t have been a bit less distracting. Hmmmm</td>', 'Excellent.  I love the simplicity of this.  Great detail and lighting. The string of twinkly lights is wonderful with the colors and the way you captured them.  I wonder if the background were solid black if it wouldn''t have been a bit less distracting. Hmmmm', '2005-12-12 00:49:14.000000', NULL, 1),
(1943491, 268051, 15711, '<td valign="top">I like the single red saturation and the guy on the kid''s trike.  I think I''d eliminate the bunny - its just added fluff that kind of detracts for me.</td>', 'I like the single red saturation and the guy on the kid''s trike.  I think I''d eliminate the bunny - its just added fluff that kind of detracts for me.', '2005-12-12 00:50:21.000000', NULL, 1),
(1943495, 267518, 37779, '<td valign="top">Wait...WHAT?! The spirit of christmas isn''t about ME getting a bunch of junk?! You simply cannot be serious! <br/>Haha, just kidding...<br/>Pretty good, but i find the red is a little TOO over powering.</td>', 'Wait...WHAT?! The spirit of christmas isn''t about ME getting a bunch of junk?! You simply cannot be serious! Haha, just kidding...Pretty good, but i find the red is a little TOO over powering.', '2005-12-12 00:50:36.000000', NULL, 1),
(1943496, 267358, 24976, '<td valign="top">i cant really see this shot in a catalog...</td>', 'i cant really see this shot in a catalog...', '2005-12-12 00:50:46.000000', NULL, 1),
(1943499, 267506, 13077, '<td valign="top">I like the lighting, and the christmas lights in the background, but I think the ring on their thumb and the sleeve on the left might be a little distracting.</td>', 'I like the lighting, and the christmas lights in the background, but I think the ring on their thumb and the sleeve on the left might be a little distracting.', '2005-12-12 00:52:05.000000', NULL, 1),
(1943501, 267555, 24976, '<td valign="top">looks really good... in the technical sense...</td>', 'looks really good... in the technical sense...', '2005-12-12 00:52:42.000000', NULL, 1),
(1943502, 267345, 22379, '<td valign="top">aint that the truth! Nice bokeh you''ve got going there also.</td>', 'aint that the truth! Nice bokeh you''ve got going there also.', '2005-12-12 00:52:47.000000', NULL, 1),
(1943508, 267449, 15711, '<td valign="top">I love the Madame Alexander doll. The clarity is good but I think it''s too busy to really look like a catalog image.  I think to really showcase her, she''d be on a page all by herself with maybe less busy things around her. I''d definitely remove the glittered rose. In fact, that might fix the whole shot for me.</td>', 'I love the Madame Alexander doll. The clarity is good but I think it''s too busy to really look like a catalog image.  I think to really showcase her, she''d be on a page all by herself with maybe less busy things around her. I''d definitely remove the glittered rose. In fact, that might fix the whole shot for me.', '2005-12-12 00:53:38.000000', NULL, 1),
