(1944561, 268300, 22734, '<td valign="top">I can taste these goodies. Great color and composition. 8</td>', 'I can taste these goodies. Great color and composition. 8', '2005-12-12 12:29:26.000000', NULL, 1),
(1944577, 268025, 35804, '<td valign="top">Ahhh...very nice...I could actually see this being in a catalog...very nice lighting and the cat''s pose is just perfect!...very well done.</td>', 'Ahhh...very nice...I could actually see this being in a catalog...very nice lighting and the cat''s pose is just perfect!...very well done.', '2005-12-12 12:32:29.000000', NULL, 1),
(1944587, 267522, 35804, '<td valign="top">Well...atleast with a house that humongous they should be able to afford the atrociuos electric bill they''ll be getting eh? I just love it when people go overboard with their Christmas decorating...kinda makes ya smile.</td>', 'Well...atleast with a house that humongous they should be able to afford the atrociuos electric bill they''ll be getting eh? I just love it when people go overboard with their Christmas decorating...kinda makes ya smile.', '2005-12-12 12:36:04.000000', NULL, 1),
(1944594, 267357, 47487, '<td valign="top">I like the wrapped gift; that''s a nice touch. But the whites are a bit overexposed, and you lost some detail because of it.</td>', 'I like the wrapped gift; that''s a nice touch. But the whites are a bit overexposed, and you lost some detail because of it.', '2005-12-12 12:37:09.000000', NULL, 1),
(1944596, 267448, 47487, '<td valign="top">Very good set-up. Really looks like a catalog ad.</td>', 'Very good set-up. Really looks like a catalog ad.', '2005-12-12 12:38:01.000000', NULL, 1),
(1944611, 268289, 6519, '<td valign="top">You''re right. And a very merry christmas to you, too!</td>', 'You''re right. And a very merry christmas to you, too!', '2005-12-12 12:43:08.000000', NULL, 1),
(1944612, 267631, 35804, '<td valign="top">Love the B &amp; W, gives this image a great nostlagic vibe...those Anna Lee dolls scare me...my mother-in-law collects them, people seem to love them...I just think they''re a little creepy and somewhat evil looking, particularly the "people" dolls...anyway, I''m going off on a tangent now, very cool picture, great tones and I also like the background blur...very nice.</td>', 'Love the B & W, gives this image a great nostlagic vibe...those Anna Lee dolls scare me...my mother-in-law collects them, people seem to love them...I just think they''re a little creepy and somewhat evil looking, particularly the "people" dolls...anyway, I''m going off on a tangent now, very cool picture, great tones and I also like the background blur...very nice.', '2005-12-12 12:43:18.000000', NULL, 1),
(1944628, 267351, 35804, '<td valign="top">...butt paste?...I can''t stop laughing...</td>', '...butt paste?...I can''t stop laughing...', '2005-12-12 12:49:04.000000', NULL, 1),
(1944643, 268139, 45672, '<td valign="top">Nice shot.  The lighting is perfect!!!  Only mishap was cutting off the hat/halo a little.</td>', 'Nice shot.  The lighting is perfect!!!  Only mishap was cutting off the hat/halo a little.', '2005-12-12 12:56:29.000000', NULL, 1),
(1944646, 268305, 45672, '<td valign="top">Great lighting.  Shadow is great.  I could see this in the Pottery barn catalog.</td>', 'Great lighting.  Shadow is great.  I could see this in the Pottery barn catalog.', '2005-12-12 12:57:16.000000', NULL, 1),
(1944654, 267431, 45672, '<td valign="top">Cool idea.  It is a little over exposed in my opinion.  I think there would be a little more impact if it were slightly darker and the "lights" got to shine a little more.</td>', 'Cool idea.  It is a little over exposed in my opinion.  I think there would be a little more impact if it were slightly darker and the "lights" got to shine a little more.', '2005-12-12 12:58:35.000000', NULL, 1),
(1944658, 268268, 45672, '<td valign="top">Nicely done.  The lighting is amazing.  The frame seems a little unlevel, but this is a good shot.  +8</td>', 'Nicely done.  The lighting is amazing.  The frame seems a little unlevel, but this is a good shot.  +8', '2005-12-12 13:00:08.000000', NULL, 1),
(1944661, 267792, 45672, '<td valign="top">This is perfect for a catalog.  If only it were completely in focus.  The lighting is just right!</td>', 'This is perfect for a catalog.  If only it were completely in focus.  The lighting is just right!', '2005-12-12 13:01:49.000000', NULL, 1),
(1944664, 267403, 45672, '<td valign="top">Well, she''s a little too dark for a catalog I''m afrain.  This is the right idea, but the shadows on her face take away from the shot.</td>', 'Well, she''s a little too dark for a catalog I''m afrain.  This is the right idea, but the shadows on her face take away from the shot.', '2005-12-12 13:02:58.000000', NULL, 1),
(1944672, 267305, 45672, '<td valign="top">There it is.  I knew there had to be a perfect one in here somewhere.  The lighting is great, it fits the criteria, nice focus.  It belongs in a hallmark catalog or something.  Way to go.</td>', 'There it is.  I knew there had to be a perfect one in here somewhere.  The lighting is great, it fits the criteria, nice focus.  It belongs in a hallmark catalog or something.  Way to go.', '2005-12-12 13:05:18.000000', NULL, 1);
