(1954152, 268279, 28471, '<td valign="top">Simple yet effective composition.  Technically proficient howeever the point of interest is dead center which tends to make the photo less interesting.</td>', 'Simple yet effective composition.  Technically proficient howeever the point of interest is dead center which tends to make the photo less interesting.', '2005-12-15 13:56:05.000000', NULL, 1),
(1954157, 267930, 28471, '<td valign="top">I like the diagonal created by the candle holder.  The lighting is great.  Good job isolating your subject. (8)</td>', 'I like the diagonal created by the candle holder.  The lighting is great.  Good job isolating your subject. (8)', '2005-12-15 13:56:58.000000', NULL, 1),
(1954159, 267257, 8367, '<td valign="top">I love this idea and the focus, clarity and colors are great. The composition would be improved, imho, if the candy was edge to edge. The left hand side has too much white space.</td>', 'I love this idea and the focus, clarity and colors are great. The composition would be improved, imho, if the candy was edge to edge. The left hand side has too much white space.', '2005-12-15 13:57:42.000000', NULL, 1),
(1954160, 267523, 28471, '<td valign="top">I can''t see how this meets the challenge.</td>', 'I can''t see how this meets the challenge.', '2005-12-15 13:57:43.000000', NULL, 1),
(1954166, 267257, 28471, '<td valign="top">Classic use of contrasting colors.  Good job. (7)</td>', 'Classic use of contrasting colors.  Good job. (7)', '2005-12-15 13:58:23.000000', NULL, 1),
(1954171, 267895, 28471, '<td valign="top">I like the compostion of this photo but I feel that the contrast the red berries bring to the photo is underutilzed due the color cast.</td>', 'I like the compostion of this photo but I feel that the contrast the red berries bring to the photo is underutilzed due the color cast.', '2005-12-15 13:59:27.000000', NULL, 1),
(1954185, 267305, 8367, '<td valign="top">Cute. Nice even light on your subject. The background color is really green. Like ouch! it hurts my eyes green but it works for a catalog shot. Not too fond of the border.</td>', 'Cute. Nice even light on your subject. The background color is really green. Like ouch! it hurts my eyes green but it works for a catalog shot. Not too fond of the border.', '2005-12-15 14:02:06.000000', NULL, 1),
(1954202, 267720, 28471, '<td valign="top">Good compoistion.  I like the soft lighting also. (8)</td>', 'Good compoistion.  I like the soft lighting also. (8)', '2005-12-15 14:07:06.000000', NULL, 1),
(1954206, 267619, 28471, '<td valign="top">Excellent photo but I don''t really feel it fits the challenge.</td>', 'Excellent photo but I don''t really feel it fits the challenge.', '2005-12-15 14:07:31.000000', NULL, 1),
(1954210, 267188, 28471, '<td valign="top">Santa is too centered.  The photo is underexposed and blurry.  Try to use a tripod or a wider aperture/faster shutter speed next time.</td>', 'Santa is too centered.  The photo is underexposed and blurry.  Try to use a tripod or a wider aperture/faster shutter speed next time.', '2005-12-15 14:08:39.000000', NULL, 1),
(1954213, 267345, 28471, '<td valign="top">You''re probably getting a lot flack on this one.  I like the composition.  Creative idea.  The light green contrast a little bit too much with the red but other than that good job.</td>', 'You''re probably getting a lot flack on this one.  I like the composition.  Creative idea.  The light green contrast a little bit too much with the red but other than that good job.', '2005-12-15 14:09:44.000000', NULL, 1),
(1954215, 267873, 28471, '<td valign="top">Good idea but there is a lot of chromatic noise in the shadow area.</td>', 'Good idea but there is a lot of chromatic noise in the shadow area.', '2005-12-15 14:10:39.000000', NULL, 1),
(1954511, 267506, 24454, '<td valign="top">I really like the composition of this.  The Christmas tree sparkles in the background are a great touch!</td>', 'I really like the composition of this.  The Christmas tree sparkles in the background are a great touch!', '2005-12-15 16:43:02.000000', NULL, 1);
